<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '@/lib/api'
import { verifyAdminAccess } from '@/lib/auth'
import { useRoute, useRouter } from 'vue-router'
type Experience = { id: string; role: string; organization: string; organizationUrl: string | null; location: string | null; startDate: string; endDate: string | null; summary: string; displayOrder: number }
type Member = { id: string; slug: string; name: string; headline: string | null; biography: string | null; photoUrl: string | null; experiences: Experience[] }
const router = useRouter(); const route = useRoute(); const memberSlug = () => String(route.params.slug ?? 'ryan'); const member = ref<Member | null>(null); const error = ref(''); const uploadStatus = ref(''); const profileStatus = ref(''); const profile = ref({ slug: '', name: '', headline: '', biography: '', photoUrl: '' }); const xp = ref({ role: '', organization: '', organizationUrl: '', location: '', startDate: '', endDate: '', summary: '', displayOrder: '0' })
async function load() { member.value = await api<Member>(`/members/${memberSlug()}`); const m = member.value; profile.value = { slug: m.slug, name: m.name, headline: m.headline ?? '', biography: m.biography ?? '', photoUrl: m.photoUrl ?? '' } }
async function saveProfile() { if (!member.value) return; error.value = ''; profileStatus.value = 'Saving profile…'; try { await api(`/members/${member.value.id}`, { method: 'PUT', body: JSON.stringify(profile.value) }); await load(); profileStatus.value = 'Profile saved successfully.' } catch (reason) { profileStatus.value = ''; error.value = reason instanceof Error ? `Profile save failed: ${reason.message}` : 'Profile save failed.' } }
function imageDataUrl(photo: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => typeof reader.result === 'string' ? resolve(reader.result) : reject(new Error('The image could not be read.')); reader.onerror = () => reject(new Error('The image could not be read.')); reader.readAsDataURL(photo) }) }
async function uploadPhoto(event: Event) { const photo = (event.target as HTMLInputElement).files?.[0]; if (!photo || !member.value) return; error.value = ''; uploadStatus.value = 'Preparing photo…'; try { const photoUrl = await imageDataUrl(photo); uploadStatus.value = 'Saving photo…'; await api(`/members/${member.value.id}`, { method: 'PUT', body: JSON.stringify({ ...profile.value, photoUrl }) }); await load(); uploadStatus.value = 'Photo uploaded successfully.' } catch (reason) { uploadStatus.value = ''; error.value = reason instanceof Error ? `Photo upload failed: ${reason.message}` : 'Photo upload failed.' } }
async function addExperience() { if (!member.value) return; await api(`/members/${member.value.id}/experiences`, { method: 'POST', body: JSON.stringify({ ...xp.value, endDate: xp.value.endDate || null, displayOrder: Number(xp.value.displayOrder) }) }); xp.value = { role: '', organization: '', organizationUrl: '', location: '', startDate: '', endDate: '', summary: '', displayOrder: '0' }; await load() }
async function removeExperience(id: string) { if (window.confirm('Delete this experience?')) { await api(`/members/experiences/${id}`, { method: 'DELETE' }); await load() } }
onMounted(async () => { if (!await verifyAdminAccess()) return router.replace('/admin'); try { await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load this member.' } })
</script>
<template><main class="min-h-svh bg-canvas px-5 py-10 text-ink sm:px-5 lg:px-20"><section class="mx-auto max-w-5xl"><RouterLink to="/admin" class="text-sm font-bold text-primary">← Back to admin</RouterLink><header class="mt-7 border-b border-ink/15 pb-7"><p class="text-xs font-bold tracking-[.14em] text-primary uppercase">Members</p><h1 class="mt-3 font-serif text-5xl">{{ member?.name ?? 'Member' }}’s profile</h1></header><p v-if="error" class="mt-6 text-red-500">{{ error }}</p><div v-if="member" class="mt-10 grid gap-8 lg:grid-cols-2"><form class="panel space-y-3" @submit.prevent="saveProfile"><h2>Profile & photo</h2><input v-model="profile.name" class="input" placeholder="Name" required /><input v-model="profile.headline" class="input" placeholder="Headline" /><input v-if="!profile.photoUrl.startsWith('data:image/')" v-model="profile.photoUrl" class="input" placeholder="Photo URL" /><p v-else class="text-sm text-muted-ink">A local photo is saved for this profile.</p><label class="upload"><span>Upload from this device</span><input accept="image/jpeg,image/png,image/webp" type="file" @change="uploadPhoto" /></label><small>JPG, PNG, or WebP; maximum 5 MB.</small><p v-if="uploadStatus" class="text-sm font-semibold text-primary">{{ uploadStatus }}</p><textarea v-model="profile.biography" class="input min-h-32" placeholder="Biography"></textarea><button class="button w-full">Save profile</button><p v-if="profileStatus" class="text-sm font-semibold text-primary">{{ profileStatus }}</p></form><section class="panel"><h2>Add experience</h2><form class="mt-5 space-y-3" @submit.prevent="addExperience"><input v-model="xp.role" class="input" placeholder="Role" required /><input v-model="xp.organization" class="input" placeholder="Organization" required /><input v-model="xp.organizationUrl" class="input" type="url" placeholder="Organization URL" /><input v-model="xp.location" class="input" placeholder="Location and work mode" /><div class="grid grid-cols-2 gap-3"><input v-model="xp.startDate" class="input" type="date" required /><input v-model="xp.endDate" class="input" type="date" /></div><textarea v-model="xp.summary" class="input min-h-24" placeholder="Summary" required></textarea><input v-model="xp.displayOrder" class="input" type="number" placeholder="Display order" required /><button class="button w-full">Add experience</button></form><div class="mt-6 space-y-3"><div v-for="item in member.experiences" :key="item.id" class="item"><span><b>{{ item.role }}</b><small>{{ item.organization }}</small></span><button class="text-sm font-bold text-red-600" @click="removeExperience(item.id)">Delete</button></div></div></section></div></section></main></template>
<style scoped>.panel{border:1px solid color-mix(in srgb,var(--color-ink) 15%,transparent);border-radius:1.5rem;padding:1.5rem}.panel h2{font-family:var(--font-serif);font-size:1.875rem}.input{width:100%;border:1px solid color-mix(in srgb,var(--color-ink) 18%,transparent);border-radius:.75rem;background:white;padding:.75rem 1rem;color:var(--color-ink)}.upload{display:flex;cursor:pointer;align-items:center;justify-content:center;border:1px dashed var(--color-primary);border-radius:.75rem;padding:.75rem 1rem;color:var(--color-primary);font-weight:700}.upload input{display:none}.panel small{display:block;color:var(--color-muted-ink)}.button{border-radius:.75rem;background:var(--color-primary);padding:.75rem 1rem;color:white;font-weight:700}.item{display:flex;justify-content:space-between;border:1px solid color-mix(in srgb,var(--color-ink) 12%,transparent);border-radius:.75rem;padding:.75rem}.item b,.item small{display:block}.item small{color:var(--color-muted-ink)}</style>
